<?php
function office_shop_wallet_contribution(array $bill): float {
    $paid=round((float)($bill['paid_amount']??0),2);$grand=round((float)($bill['total_amount']??0),2);$government=round((float)($bill['gov_fee_total']??0),2);$service=round((float)($bill['subtotal']??0)-$government,2);$isCredit=(string)($bill['payment_mode']??'')==='Credit';
    if($isCredit&&$paid<$government)return 0.0;
    if(abs($paid-$grand)<0.005)return $service;
    if(abs($paid-$government)<0.005)return 0.0;
    if($paid>$government)return round($paid-$government,2);
    if($paid>=1&&$paid<$government)return -round($grand-$service-$paid,2);
    if($paid<1)return -$government;
    return 0.0;
}
function office_shop_wallet_balances(PDO $pdo,int $companyId,int $excludeMovementId=0,int $excludeTransferId=0): array {
    $cash=0.0;$bank=0.0;$q=$pdo->prepare('SELECT id,payment_mode,payment_method,subtotal,total_amount,paid_amount,gov_fee_total FROM office_bills WHERE company_id=?');$q->execute([$companyId]);foreach($q->fetchAll(PDO::FETCH_ASSOC) as $bill){$method=(string)$bill['payment_method'];$value=(string)$bill['payment_mode']==='Credit'?-round((float)$bill['gov_fee_total'],2):office_shop_wallet_contribution($bill);if($method==='Cash')$cash+=$value;elseif(in_array($method,['Card','Bank','Tabby','Tamara'],true))$bank+=$value;}
    $q=$pdo->prepare("SELECT p.payment_method,p.amount FROM office_bill_payments p JOIN office_bills b ON b.id=p.bill_id AND b.company_id=p.company_id WHERE p.company_id=? AND b.payment_mode='Credit' AND p.payment_method<>'Wallet Credit'");$q->execute([$companyId]);foreach($q->fetchAll(PDO::FETCH_ASSOC) as $payment){if($payment['payment_method']==='Cash')$cash+=(float)$payment['amount'];elseif(in_array($payment['payment_method'],['Card','Bank','Tabby','Tamara'],true))$bank+=(float)$payment['amount'];}
    $q=$pdo->prepare('SELECT id,movement_type,wallet_account,amount FROM office_shop_wallet_movements WHERE company_id=?');$q->execute([$companyId]);foreach($q->fetchAll(PDO::FETCH_ASSOC) as $r){if((int)$r['id']===$excludeMovementId)continue;$v=(float)$r['amount'];if($r['wallet_account']==='Cash')$cash+=$r['movement_type']==='Deposit'?$v:-$v;else $bank+=$r['movement_type']==='Deposit'?$v:-$v;}
    $q=$pdo->prepare('SELECT id,amount FROM office_shop_wallet_transfers WHERE company_id=?');$q->execute([$companyId]);foreach($q->fetchAll(PDO::FETCH_ASSOC) as $r){if((int)$r['id']===$excludeTransferId)continue;$cash-=(float)$r['amount'];$bank+=(float)$r['amount'];}$q=$pdo->prepare('SELECT wallet_account,amount FROM office_shop_expenses WHERE company_id=?');$q->execute([$companyId]);foreach($q->fetchAll(PDO::FETCH_ASSOC) as $r){if($r['wallet_account']==='Bank')$bank-=(float)$r['amount'];else $cash-=(float)$r['amount'];}return ['cash'=>round($cash,2),'bank'=>round($bank,2)];
}

